import { useMemo } from "react";

/** A single selectable option passed to combobox or multi-select components. */
export type SelectionOption<T extends string> = {
  /** Unique identifier — also the value submitted on selection. */
  value: T;
  /** Human-readable label shown in the list and the trigger input. */
  label: string;
  /** When `true` the option is rendered but cannot be selected. */
  disabled?: boolean;
};

type UseFilteredOptionsProps<T extends string> = {
  /** Full list of options to filter. */
  items: SelectionOption<T>[];
  /** Current search query. */
  query: string;
  /**
   * Skip local filtering entirely.
   * Set to `true` when filtering is handled server-side and `items` is
   * already the correct subset for the current query.
   * @default false
   */
  disableLocalFilter?: boolean;
  /**
   * Custom predicate. Receives each option and the raw query string.
   * When provided, replaces the default case-insensitive label match.
   */
  filterFn?: (item: SelectionOption<T>, query: string) => boolean;
};

/**
 * Returns a memoized filtered subset of `items` based on `query`.
 *
 * Falls back to a case-insensitive `label.includes(query)` match when no
 * `filterFn` is supplied. Returns all items when `disableLocalFilter` is
 * `true` or the query is empty / whitespace-only.
 */
export function useFilteredOptions<T extends string>({
  items,
  query,
  disableLocalFilter = false,
  filterFn,
}: UseFilteredOptionsProps<T>) {
  return useMemo(() => {
    if (disableLocalFilter || !query.trim()) {
      return items;
    }
    if (filterFn) {
      return items.filter((item) => filterFn(item, query));
    }
    const normalizedQuery = query.toLowerCase();
    return items.filter((item) =>
      item.label.toLowerCase().includes(normalizedQuery),
    );
  }, [items, query, disableLocalFilter, filterFn]);
}
